// Implement a fixed-size lock-free single-producer single-consumer ring buffer for uint8_t.
// API (implement exactly these, C99, no dynamic allocation, MISRA-C compliant):
//   void rb_init(ring_buffer_t *rb);
//   bool rb_push(ring_buffer_t *rb, uint8_t byte);   // false if full
//   bool rb_pop(ring_buffer_t *rb, uint8_t *out);    // false if empty
// Use this struct:
//   #define RB_SIZE 64u
//   typedef struct { uint8_t buf[RB_SIZE]; volatile uint32_t head; volatile uint32_t tail; } ring_buffer_t;
